        McqQuestion(id: "sci6_c036_q2", text: "Sweating cools the body because:", options: ["Sweat is cold when produced", "Sweat evaporates and takes heat away from the skin", "Sweat adds water to the body", "Sweat blocks heat from the sun"], correctIndex: 1, explanation: "Sweat evaporates from skin, absorbing body heat — this cools you down."),
        McqQuestion(id: "sci6_c036_q3", text: "A clay pot (matka) keeps water cool because:", options: ["Clay absorbs sunlight", "Water seeps through tiny pores and evaporates, cooling the remaining water", "Clay is naturally cold", "Clay blocks heat completely"], correctIndex: 1, explanation: "Water seeps through the porous clay and evaporates from the outer surface, drawing heat from the water inside."),
        McqQuestion(id: "sci6_c036_q4", text: "Doctors swab the skin with spirit (alcohol) before an injection. The cold feeling is due to:", options: ["Spirit being colder than skin", "Spirit evaporating quickly and absorbing heat from the skin", "Injection reducing temperature", "Spirit blocking nerves"], correctIndex: 1, explanation: "Alcohol evaporates very quickly and absorbs heat from the skin — you feel a cooling sensation."),
        McqQuestion(id: "sci6_c036_q5", text: "Which has a greater cooling effect — faster or slower evaporation?", options: ["Slower evaporation cools more", "Faster evaporation cools more", "They have the same effect", "Evaporation does not cause cooling"], correctIndex: 1, explanation: "Faster evaporation removes heat from the surface more quickly — producing a greater cooling effect.")
    ]

    private static let sci6_c037: [McqQuestion] = [
