        McqQuestion(id: "sci6_c037_q2", text: "The correct order in the water cycle is:", options: ["Rain → Evaporation → Condensation", "Evaporation → Condensation → Precipitation", "Condensation → Rain → Evaporation", "Freezing → Melting → Boiling"], correctIndex: 1, explanation: "Sun evaporates water → it rises and condenses into clouds → precipitation (rain/snow) falls → cycle repeats."),
        McqQuestion(id: "sci6_c037_q3", text: "Snow falls when:", options: ["Clouds are very white", "Water droplets in clouds freeze into ice crystals", "Wind blows clouds apart", "The sun is very bright"], correctIndex: 1, explanation: "If the temperature is below 0°C in the cloud (and on the way down), water freezes into snow crystals."),
        McqQuestion(id: "sci6_c037_q4", text: "Mountains often have heavy rainfall on one side because:", options: ["Mountains produce water", "Moist air is forced upward, cools and condenses", "The sun shines more there", "Trees attract rain"], correctIndex: 1, explanation: "When moist air hits mountains, it rises, cools, and water vapour condenses — causing rain on the windward side."),
        McqQuestion(id: "sci6_c037_q5", text: "The water cycle is important because:", options: ["It makes rivers disappear", "It continuously replenishes fresh water on Earth", "It causes droughts", "It only benefits oceans"], correctIndex: 1, explanation: "The water cycle constantly renews fresh water in rivers, lakes and ground — essential for all life on land.")
    ]

    // MARK: - Unit 9: Methods of Separation

