        McqQuestion(id: "sci6_c038_q2", text: "Removing stones from rice before cooking is an example of:", options: ["Sieving", "Handpicking", "Filtration", "Evaporation"], correctIndex: 1, explanation: "Handpicking — using fingers to manually remove unwanted larger particles — is the method used."),
