        McqQuestion(id: "sci6_c038_q4", text: "Salt water is separated by:", options: ["Sieving", "Magnetic separation", "Evaporation of water", "Filtration through cloth"], correctIndex: 2, explanation: "Heating salt water evaporates the water, leaving dry salt behind — this is evaporation/crystallisation."),
        McqQuestion(id: "sci6_c038_q5", text: "Why is separation important in industry?", options: ["It makes products look colourful", "Petroleum, metals, chemicals etc. must be purified from their raw mixtures", "It reduces the weight of products", "It is only useful in kitchens"], correctIndex: 1, explanation: "Industries separate crude oil into petrol, diesel, kerosene; ores into metals — separation is fundamental to manufacturing.")
    ]

    private static let sci6_c039: [McqQuestion] = [
        McqQuestion(id: "sci6_c039_q1", text: "Threshing is used to separate:", options: ["Sand from salt", "Grain from stalks after harvesting", "Oil from water", "Iron from copper"], correctIndex: 1, explanation: "Threshing beats harvested crop to separate grains from the stalks/chaff."),
        McqQuestion(id: "sci6_c039_q2", text: "Winnowing separates grain from chaff by using:", options: ["Water", "Wind (air current)", "Heat", "A sieve"], correctIndex: 1, explanation: "Winnowing tosses the mixture into the air — lighter chaff blows away, heavier grains fall down."),
        McqQuestion(id: "sci6_c039_q3", text: "Handpicking is suitable when the components to be separated are:", options: ["Very fine and similar", "Clearly different in size or appearance and few in number", "Mixed in water", "Magnetic"], correctIndex: 1, explanation: "Handpicking works only when differences are visible and the quantity is small enough to pick by hand."),
        McqQuestion(id: "sci6_c039_q4", text: "A farmer uses winnowing to separate:", options: ["Pebbles from soil", "Unhusked rice from husked rice", "Husk (chaff) from wheat grain", "Sand from gravel"], correctIndex: 2, explanation: "Husk is much lighter than grain — wind blows it away while grain falls to the ground."),
        McqQuestion(id: "sci6_c039_q5", text: "In which direction does a farmer throw a grain-chaff mixture during winnowing?", options: ["Against the wind", "Into the wind (so wind carries chaff away)", "Straight up with no wind", "Downward on the ground"], correctIndex: 1, explanation: "The mixture is thrown into the wind — wind carries lighter chaff away; heavier grain falls nearby.")
    ]

    private static let sci6_c040: [McqQuestion] = [
