        McqQuestion(id: "sci6_c040_q2", text: "Flour is separated from bran by:", options: ["Magnetic separation", "Winnowing", "Sieving", "Filtration"], correctIndex: 2, explanation: "A fine sieve separates the fine flour particles from the coarser bran."),
        McqQuestion(id: "sci6_c040_q3", text: "Which sieve — fine or coarse — would you use to separate sand from gravel?", options: ["Very fine sieve", "Coarse sieve with holes bigger than sand but smaller than gravel", "No sieve needed", "Any sieve works the same"], correctIndex: 1, explanation: "You need a sieve with holes larger than sand grains but smaller than gravel pebbles — sand passes through; gravel stays."),
        McqQuestion(id: "sci6_c040_q4", text: "Construction workers use sieving to:", options: ["Remove iron rods from concrete", "Separate fine sand from coarse gravel for different uses", "Mix cement and water", "Test water quality"], correctIndex: 1, explanation: "Different particle sizes of sand/gravel are needed for different construction purposes — sieving separates them."),
        McqQuestion(id: "sci6_c040_q5", text: "Which of the following CANNOT be separated by sieving?", options: ["Gravel and sand", "Salt dissolved in water", "Big stones and small stones", "Flour and rice grains"], correctIndex: 1, explanation: "Dissolved salt and water cannot be sieved because they form a solution — particles are too small and dissolved.")
    ]

    private static let sci6_c041: [McqQuestion] = [
