        McqQuestion(id: "sci6_c041_q2", text: "Decantation means:", options: ["Filtering through paper", "Carefully pouring off the clear liquid without disturbing the sediment", "Boiling the liquid away", "Using a magnet"], correctIndex: 1, explanation: "Decantation is gently pouring the clear top liquid after sediment has settled — leaving sediment behind."),
        McqQuestion(id: "sci6_c041_q3", text: "Filtration is used to separate:", options: ["Salt from water (dissolved)", "A dissolved solid from a liquid", "An insoluble solid from a liquid", "Two liquids"], correctIndex: 2, explanation: "Filtration separates insoluble solids (like sand) from liquids — the solid stays in the filter, liquid passes through."),
        McqQuestion(id: "sci6_c041_q4", text: "In filtration, the liquid that passes through the filter is called the:", options: ["Residue", "Filtrate", "Sediment", "Solution"], correctIndex: 1, explanation: "The liquid that passes through the filter paper is called the filtrate."),
        McqQuestion(id: "sci6_c041_q5", text: "Why does adding alum (fitkari) to muddy water help?", options: ["Alum dissolves mud completely", "Alum makes mud particles clump together and settle faster", "Alum kills bacteria", "Alum makes water taste better"], correctIndex: 1, explanation: "Alum causes clay/mud particles to aggregate (flocculate) and settle quickly — a traditional water-purification step.")
    ]

