        McqQuestion(id: "sci6_c042_q2", text: "Condensation (collecting cooled vapour) after evaporation allows you to:", options: ["Get the salt", "Recover the pure water as well as the dissolved substance", "Destroy the mixture", "Change its colour"], correctIndex: 1, explanation: "Distillation combines evaporation + condensation — the vapour is cooled and collected as pure liquid."),
        McqQuestion(id: "sci6_c042_q3", text: "Sea salt is produced commercially by:", options: ["Filtering sea water through sand", "Allowing sea water to evaporate in shallow pans", "Boiling sea water rapidly", "Using magnets on sea water"], correctIndex: 1, explanation: "Salt pans allow seawater to evaporate slowly in the sun — leaving salt crystals behind."),
        McqQuestion(id: "sci6_c042_q4", text: "Evaporation is NOT suitable to separate:", options: ["Salt and water", "Sugar and water", "Oil and water (immiscible liquids)", "Copper sulfate and water"], correctIndex: 2, explanation: "Oil and water don't mix — evaporation wouldn't separate them. A separating funnel is used instead."),
        McqQuestion(id: "sci6_c042_q5", text: "In distillation, which change of state happens first?", options: ["Condensation then evaporation", "Evaporation then condensation", "Freezing then melting", "Sublimation"], correctIndex: 1, explanation: "Liquid is first evaporated by heating, then the vapour is cooled and condensed back to pure liquid.")
    ]

    private static let sci6_c043: [McqQuestion] = [
