        McqQuestion(id: "sci6_c043_q2", text: "The principle behind churning is:", options: ["Magnetism", "Density difference — lighter components move outward/upward when spun", "Solubility difference", "Size difference"], correctIndex: 1, explanation: "Centrifugal effect during spinning separates components by density — lighter ones separate out."),
        McqQuestion(id: "sci6_c043_q3", text: "Magnetic separation is used to remove:", options: ["Sand from salt", "Iron filings or nails from non-magnetic materials like aluminium or sand", "Oil from water", "Larger stones from smaller ones"], correctIndex: 1, explanation: "A magnet attracts iron and steel but not other materials — ideal for removing magnetic impurities."),
        McqQuestion(id: "sci6_c043_q4", text: "Which industry uses magnetic separation?", options: ["Textile industry", "Ceramic and food industries to remove iron contamination", "Paper industry only", "Oil industry only"], correctIndex: 1, explanation: "Food and ceramic industries use magnets to remove iron particles that may have entered from machinery."),
        McqQuestion(id: "sci6_c043_q5", text: "A centrifuge spins mixtures to separate them. It works on the same principle as:", options: ["Sieving", "Churning — denser parts move outward, lighter ones inward", "Winnowing", "Filtration"], correctIndex: 1, explanation: "Like churning, centrifugation uses rotation — denser components move to the bottom/outside and separate.")
    ]

    // MARK: - Unit 10: Living Creatures

    private static let sci6_c044: [McqQuestion] = [
        McqQuestion(id: "sci6_c044_q1", text: "Which of these is a characteristic of living things?", options: ["Making sound", "Needing nutrition, growing and reproducing", "Having a fixed colour", "Being made of one material"], correctIndex: 1, explanation: "All living things need food/nutrients, grow, and reproduce — these are fundamental life characteristics."),
        McqQuestion(id: "sci6_c044_q2", text: "A rock is a non-living thing because it:", options: ["Has no colour", "Does not grow, reproduce or respond to stimuli", "Does not make sound", "Cannot be moved"], correctIndex: 1, explanation: "Rocks lack all characteristics of life — no growth, reproduction, nutrition or response to stimuli."),
        McqQuestion(id: "sci6_c044_q3", text: "Respiration in living organisms means:", options: ["Breathing in only", "The process of releasing energy from food inside cells", "Pumping blood", "Moving from place to place"], correctIndex: 1, explanation: "Cellular respiration breaks down glucose using oxygen (or without) to release energy for all life processes."),
        McqQuestion(id: "sci6_c044_q4", text: "Which is a characteristic that separates living from non-living things?", options: ["Being coloured", "Being solid", "Responding to stimuli (e.g. a plant bending toward light)", "Having a fixed shape"], correctIndex: 2, explanation: "Living things respond to stimuli — a plant grows toward light; an animal runs from danger. Non-living things do not."),
        McqQuestion(id: "sci6_c044_q5", text: "Excretion is important for living things because:", options: ["It provides energy", "It removes waste products that could be harmful if they accumulated", "It helps in reproduction", "It allows movement"], correctIndex: 1, explanation: "Excretion removes metabolic wastes (like CO₂ and urea) — keeping the internal environment stable.")
    ]

