        McqQuestion(id: "sci6_c045_q5", text: "The food store in a seed that nourishes the embryo during germination is the:", options: ["Testa (seed coat)", "Embryo", "Endosperm (or cotyledons)", "Root"], correctIndex: 2, explanation: "The endosperm or cotyledons store starch, proteins and fats that feed the embryo until it can make its own food.")
    ]

