        McqQuestion(id: "sci7_c012_q5", text: "Aluminium does not rust easily because:", options: ["It is a non-metal", "It forms a thin protective oxide layer on its surface", "It repels water", "It is magnetic"], correctIndex: 1, explanation: "Aluminium instantly forms a thin, hard aluminium oxide (Al₂O₃) layer that seals the surface and prevents further corrosion.")
    ]

