    ]

    private static let sci7_c015: [McqQuestion] = [
        McqQuestion(id: "sci7_c015_q1", text: "A physical change is one in which:", options: ["A new substance is always formed", "The substance changes appearance but remains the same material", "The change cannot be reversed", "Energy is never involved"], correctIndex: 1, explanation: "Physical changes alter shape, size or state but the chemical composition stays the same — no new substance is produced."),
        McqQuestion(id: "sci7_c015_q2", text: "Which of these is a physical change?", options: ["Burning wood", "Cooking an egg", "Melting ice into water", "Rusting of iron"], correctIndex: 2, explanation: "Ice melting is a physical change — water molecules don't change; only the state (solid to liquid) changes."),
        McqQuestion(id: "sci7_c015_q3", text: "Tearing paper is a physical change because:", options: ["New chemicals are made", "Only the shape changes — the paper is still paper", "It cannot be reversed", "Heat is produced"], correctIndex: 1, explanation: "Tearing changes size and shape, not chemical composition — the paper molecules are unchanged."),
        McqQuestion(id: "sci7_c015_q4", text: "Dissolving sugar in water is a physical change because:", options: ["Sugar is destroyed", "Sugar can be recovered by evaporating the water", "A new sweet substance forms", "Carbon dioxide is released"], correctIndex: 1, explanation: "Dissolving is physical — the sugar disperses but isn't destroyed. Evaporation recovers the original sugar crystals."),
        McqQuestion(id: "sci7_c015_q5", text: "Which is generally true about physical changes?", options: ["They always produce gases", "They are usually reversible", "They always release heat", "They change the chemical formula"], correctIndex: 1, explanation: "Physical changes are generally reversible — melted wax can solidify, dissolved salt can be recovered, stretched rubber springs back.")
    ]

    private static let sci7_c016: [McqQuestion] = [
