        McqQuestion(id: "sci7_c016_q5", text: "A sign that a chemical change has occurred includes:", options: ["Only a change in size", "Colour change, gas produced, light/heat released, or new smell", "Only a change in state", "Only dissolving"], correctIndex: 1, explanation: "Chemical changes produce observable evidence — new colours, gases (bubbling), temperature change, smell, or light indicate new substances forming.")
    ]

